const NEAR = 0.25;
const colorCache = new Map();

function parseColor(value) {
  if (Array.isArray(value)) return [value[0] | 0, value[1] | 0, value[2] | 0];
  let hex = typeof value === 'string' ? value.trim() : '#cccccc';
  if (hex[0] === '#') hex = hex.slice(1);
  if (hex.length === 3) hex = hex[0] + hex[0] + hex[1] + hex[1] + hex[2] + hex[2];
  let cached = colorCache.get(hex);
  if (cached === undefined) {
    const n = Number.parseInt(hex, 16);
    cached = Number.isFinite(n) ? [(n >> 16) & 255, (n >> 8) & 255, n & 255] : [204, 204, 204];
    colorCache.set(hex, cached);
  }
  return cached;
}

function rawBoxFaces(w, h, d) {
  const x = w / 2, y = h / 2, z = d / 2;
  return [
    { v: [[-x, y, -z], [x, y, -z], [x, y, z], [-x, y, z]], n: [0, 1, 0], shade: 1.1 },
    { v: [[-x, -y, z], [x, -y, z], [x, -y, -z], [-x, -y, -z]], n: [0, -1, 0], shade: 0.45 },
    { v: [[x, -y, -z], [x, -y, z], [x, y, z], [x, y, -z]], n: [1, 0, 0], shade: 0.84 },
    { v: [[-x, -y, z], [-x, -y, -z], [-x, y, -z], [-x, y, z]], n: [-1, 0, 0], shade: 0.72 },
    { v: [[x, -y, z], [-x, -y, z], [-x, y, z], [x, y, z]], n: [0, 0, 1], shade: 0.96 },
    { v: [[-x, -y, -z], [x, -y, -z], [x, y, -z], [-x, y, -z]], n: [0, 0, -1], shade: 0.78 },
  ];
}

function transformFace(face, px, py, pz, yaw) {
  const c = Math.cos(yaw || 0), s = Math.sin(yaw || 0);
  const v = [];
  for (let i = 0; i < face.v.length; i++) {
    const p = face.v[i];
    v.push([px + p[0] * c + p[2] * s, py + p[1], pz - p[0] * s + p[2] * c]);
  }
  const n = face.n;
  return { v, n: [n[0] * c + n[2] * s, n[1], -n[0] * s + n[2] * c], shade: face.shade };
}

function decorate(face, spec) {
  face.color = parseColor(spec.color);
  face.flat = !!spec.flat;
  face.layer = spec.layer || 0;
  face.alpha = spec.alpha === undefined ? 1 : spec.alpha;
  return face;
}

export function boxFaces(spec) {
  const raw = rawBoxFaces(spec.w || 1, spec.h || 1, spec.d || 1);
  return raw.map((face) => decorate(transformFace(face, spec.x || 0, spec.y || 0, spec.z || 0, spec.rotY || 0), spec));
}

export function createMesh() {
  return { x: 0, y: 0, z: 0, rotationY: 0, visible: true, boxes: [], faces: null, static: false };
}

export function addBox(mesh, spec) {
  const box = { x: 0, y: 0, z: 0, w: 1, h: 1, d: 1, rotY: 0, color: '#cccccc', ...spec };
  box.raw = rawBoxFaces(box.w, box.h, box.d);
  box.color = parseColor(box.color);
  mesh.boxes.push(box);
  return box;
}

export function freezeMesh(mesh) {
  const c = Math.cos(mesh.rotationY || 0), s = Math.sin(mesh.rotationY || 0);
  const faces = [];
  for (const box of mesh.boxes) {
    const bx = mesh.x + box.x * c + box.z * s;
    const bz = mesh.z - box.x * s + box.z * c;
    const yaw = (box.rotY || 0) + (mesh.rotationY || 0);
    for (const face of box.raw) {
      const out = transformFace(face, bx, mesh.y + box.y, bz, yaw);
      out.color = box.color;
      out.shade *= box.shade || 1;
      out.flat = false;
      out.layer = 0;
      faces.push(out);
    }
  }
  mesh.faces = faces;
  mesh.static = true;
  return mesh;
}

function liveFaces(mesh) {
  const c = Math.cos(mesh.rotationY || 0), s = Math.sin(mesh.rotationY || 0);
  const faces = [];
  for (const box of mesh.boxes) {
    const bx = mesh.x + box.x * c + box.z * s;
    const bz = mesh.z - box.x * s + box.z * c;
    const yaw = (box.rotY || 0) + (mesh.rotationY || 0);
    for (const face of box.raw) {
      const out = transformFace(face, bx, mesh.y + box.y, bz, yaw);
      out.color = box.color;
      out.shade *= box.shade || 1;
      out.flat = false;
      out.layer = 0;
      faces.push(out);
    }
  }
  return faces;
}

export function createScene() {
  return {
    terrain: [],
    meshes: [],
    sun: [-0.45, 0.82, 0.36],
    fog: [214, 229, 235],
    skyTop: [70, 151, 211],
    skyLow: [220, 233, 228],
  };
}

export function addGround(scene, points, color, layer = 0) {
  scene.terrain.push({ v: points, n: [0, 1, 0], shade: 1, color: parseColor(color), flat: true, layer });
}

export function addMesh(scene, mesh) {
  scene.meshes.push(mesh);
  return mesh;
}

function clampColor(n) {
  return n < 0 ? 0 : n > 255 ? 255 : n | 0;
}

function clipNear(poly) {
  const out = [];
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i], b = poly[(i + 1) % poly.length];
    const ain = a.z >= NEAR, bin = b.z >= NEAR;
    if (ain) out.push(a);
    if (ain !== bin) {
      const t = (NEAR - a.z) / (b.z - a.z);
      out.push({ x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t, z: NEAR });
    }
  }
  return out;
}

export function createRenderer(canvas) {
  const ctx = canvas.getContext('2d', { alpha: false });
  let width = 1, height = 1;

  function resize() {
    const ratio = Math.min(window.devicePixelRatio || 1, 2);
    const cssW = Math.max(1, canvas.clientWidth || window.innerWidth);
    const cssH = Math.max(1, canvas.clientHeight || window.innerHeight);
    width = Math.round(cssW * ratio);
    height = Math.round(cssH * ratio);
    if (canvas.width !== width || canvas.height !== height) {
      canvas.width = width;
      canvas.height = height;
    }
  }

  function paintSky(scene, camera, basis, focal) {
    const horizon = Math.max(-height, Math.min(height * 2, height * 0.5 + Math.tan(camera.pitch || 0) * focal));
    const grad = ctx.createLinearGradient(0, 0, 0, Math.max(1, horizon + height * 0.22));
    grad.addColorStop(0, `rgb(${scene.skyTop.map(clampColor).join(',')})`);
    grad.addColorStop(1, `rgb(${scene.skyLow.map(clampColor).join(',')})`);
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);

    const sx = scene.sun[0] * 460, sy = scene.sun[1] * 460, sz = scene.sun[2] * 460;
    const vz = sx * basis.fx + sy * basis.fy + sz * basis.fz;
    if (vz > NEAR) {
      const vx = sx * basis.rx + sy * basis.ry + sz * basis.rz;
      const vy = sx * basis.ux + sy * basis.uy + sz * basis.uz;
      const px = width * 0.5 + vx * focal / vz;
      const py = height * 0.5 - vy * focal / vz;
      const radius = Math.max(width, height) * 0.42;
      const glow = ctx.createRadialGradient(px, py, 0, px, py, radius);
      glow.addColorStop(0, 'rgba(255,248,214,0.55)');
      glow.addColorStop(0.22, 'rgba(255,234,174,0.18)');
      glow.addColorStop(1, 'rgba(255,230,180,0)');
      ctx.fillStyle = glow;
      ctx.fillRect(0, 0, width, height);
    }
  }

  function render(scene, camera) {
    resize();
    const fov = ((camera.fov || 70) * Math.PI) / 180;
    const focal = height * 0.5 / Math.tan(fov * 0.5);
    const yaw = camera.yaw || 0, pitch = camera.pitch || 0;
    const cp = Math.cos(pitch), sp = Math.sin(pitch), sy = Math.sin(yaw), cy = Math.cos(yaw);
    const basis = {
      fx: sy * cp, fy: sp, fz: cy * cp,
      rx: cy, ry: 0, rz: -sy,
      ux: -sp * sy, uy: cp, uz: -sp * cy,
    };
    paintSky(scene, camera, basis, focal);

    const terrainBatch = [], objectBatch = [];
    const cx = camera.x || 0, cy0 = camera.y || 2, cz = camera.z || 0;

    function prepare(face, out) {
      const v = face.v;
      const mx = (v[0][0] + v[1][0] + v[2][0] + v[3][0]) * 0.25;
      const my = (v[0][1] + v[1][1] + v[2][1] + v[3][1]) * 0.25;
      const mz = (v[0][2] + v[1][2] + v[2][2] + v[3][2]) * 0.25;
      if (!face.flat) {
        const dx = cx - mx, dy = cy0 - my, dz = cz - mz;
        if (face.n[0] * dx + face.n[1] * dy + face.n[2] * dz <= 0) return;
      }
      const poly = [];
      for (let i = 0; i < v.length; i++) {
        const dx = v[i][0] - cx, dy = v[i][1] - cy0, dz = v[i][2] - cz;
        poly.push({
          x: dx * basis.rx + dy * basis.ry + dz * basis.rz,
          y: dx * basis.ux + dy * basis.uy + dz * basis.uz,
          z: dx * basis.fx + dy * basis.fy + dz * basis.fz,
        });
      }
      const clipped = clipNear(poly);
      if (clipped.length < 3) return;
      let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity, depth = 0;
      const pts = [];
      for (let i = 0; i < clipped.length; i++) {
        const p = clipped[i];
        const sx = width * 0.5 + p.x * focal / p.z;
        const py = height * 0.5 - p.y * focal / p.z;
        pts.push(sx, py);
        if (sx < minX) minX = sx;
        if (sx > maxX) maxX = sx;
        if (py < minY) minY = py;
        if (py > maxY) maxY = py;
        depth += p.z;
      }
      if (maxX < 0 || minX > width || maxY < 0 || minY > height) return;
      out.push({ pts, face, depth: depth / clipped.length });
    }

    for (let i = 0; i < scene.terrain.length; i++) prepare(scene.terrain[i], terrainBatch);
    for (let i = 0; i < scene.meshes.length; i++) {
      const mesh = scene.meshes[i];
      if (!mesh.visible) continue;
      const faces = mesh.static ? mesh.faces : liveFaces(mesh);
      for (let j = 0; j < faces.length; j++) prepare(faces[j], objectBatch);
    }

    terrainBatch.sort((a, b) => a.face.layer - b.face.layer || b.depth - a.depth);
    objectBatch.sort((a, b) => b.depth - a.depth);

    const sun = scene.sun;
    const fog = scene.fog;
    const sunLen = Math.hypot(sun[0], sun[1], sun[2]) || 1;
    const slx = sun[0] / sunLen, sly = sun[1] / sunLen, slz = sun[2] / sunLen;

    function draw(batch) {
      for (let i = 0; i < batch.length; i++) {
        const item = batch[i], face = item.face, base = face.color;
        const light = 0.66 + 0.34 * Math.max(0, face.n[0] * slx + face.n[1] * sly + face.n[2] * slz);
        const k = face.shade * light;
        let fogMix = Math.max(0, Math.min(0.78, (item.depth - 115) / 420));
        if (face.flat) fogMix = Math.min(0.9, fogMix + 0.06);
        const r = clampColor(base[0] * k * (1 - fogMix) + fog[0] * fogMix);
        const g = clampColor(base[1] * k * (1 - fogMix) + fog[1] * fogMix);
        const b = clampColor(base[2] * k * (1 - fogMix) + fog[2] * fogMix);
        const pts = item.pts;
        ctx.beginPath();
        ctx.moveTo(pts[0], pts[1]);
        for (let p = 2; p < pts.length; p += 2) ctx.lineTo(pts[p], pts[p + 1]);
        ctx.closePath();
        ctx.fillStyle = `rgb(${r},${g},${b})`;
        ctx.fill();
      }
    }
    draw(terrainBatch);
    draw(objectBatch);
  }

  resize();
  window.addEventListener('resize', resize);
  return { render, resize, canvas, get width() { return width; }, get height() { return height; } };
}
